int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (!from || !to || fromlen <= 0 || tolen <= 0) {
        return -EINVAL;
    }

    while (i < fromlen && j < tolen - 1) {
        if (from[i] == '\0') {
            to[j++] = '\\';
            if (j >= tolen - 1) {
                return -ERANGE;
            }
            to[j++] = '0';
        } else if (from[i] == '/') {
            if (j > 0 && to[j - 1] != '/') {
                to[j++] = '/';
            }
        } else if (from[i] == '.') {
            if (i + 1 < fromlen && from[i + 1] == '.' && (i + 2 == fromlen || from[i + 2] == '/')) {
                if (j > 0 && to[j - 1] != '/') {
                    to[j++] = '.';
                    if (j >= tolen - 1) {
                        return -ERANGE;
                    }
                    to[j++] = '.';
                } else {
                    return -EINVAL;
                }
                i += 2;
                continue;
            } else if (i + 1 < fromlen && from[i + 1] == '/') {
                i++;
                continue;
            } else {
                to[j++] = from[i];
            }
        } else {
            to[j++] = from[i];
        }
        i++;
    }

    if (i < fromlen) {
        return -ERANGE;
    }

    to[j] = '\0';
    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (tolen <= 0 || fromlen <= 0) {
        return -EINVAL;
    }

    while (i < fromlen && j < tolen - 1) {
        if (from[i] == 0) {
            // Null byte encountered, treat as end of component
            break;
        } else if (from[i] == '/') {
            // Directory separator, add to result
            to[j++] = '/';
        } else if (from[i] == '.') {
            // Handle dot notation
            if (i + 1 < fromlen && from[i + 1] == '.' && (i + 2 >= fromlen || from[i + 2] == 0)) {
                // "../" notation
                if (j + 3 > tolen - 1) {
                    return -ENAMETOOLONG;
                }
                to[j++] = '.';
                to[j++] = '.';
                to[j++] = '/';
                i += 2;
            } else {
                // Simple "." or part of filename
                to[j++] = '.';
            }
        } else {
            // Regular character, add to result
            to[j++] = from[i];
        }
        i++;
    }

    to[j] = '\0';

    if (i < fromlen) {
        // Input not fully processed, buffer might be too small
        return -ENAMETOOLONG;
    }

    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    while (i < fromlen && j < tolen - 1) {
        if (from[i] == 0) {
            // End of components
            break;
        }

        if (from[i] == 1) {
            // Symlink indicator
            if (j + 8 > tolen - 1) {
                return -ENAMETOOLONG;
            }
            memcpy(&to[j], "SYMLINK", 8);
            j += 8;
        } else if (from[i] == 2) {
            // Directory indicator
            if (j + 10 > tolen - 1) {
                return -ENAMETOOLONG;
            }
            memcpy(&to[j], "DIRECTORY", 10);
            j += 10;
        } else if (from[i] >= 32 && from[i] <= 126) {
            // Printable ASCII character
            to[j++] = from[i];
        } else {
            // Invalid character
            return -EINVAL;
        }

        i++;
    }

    if (i < fromlen) {
        return -EINVAL;
    }

    if (j >= tolen) {
        return -ENAMETOOLONG;
    }

    to[j] = '\0';

    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (tolen <= 0 || fromlen <= 0) {
        return -EINVAL;
    }

    while (i < fromlen && j < tolen - 1) {
        unsigned char c = from[i++];

        if (c == '\0') {
            continue;
        }

        if (c == '.') {
            if (j > 0 && to[j - 1] == '/') {
                continue;
            }
        }

        if (c == '/' && to[j - 1] == '/') {
            continue;
        }

        if (c == '/' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '.') {
            to[j++] = c;
        } else if (c == SYMLINK_MAGIC) {
            int name_len = from[i];
            i++;
            if (i + name_len > fromlen) {
                return -EFAULT;
            }
            while (name_len-- > 0 && j < tolen - 1) {
                to[j++] = from[i++];
            }
        } else if (c == DIR_MAGIC) {
            if (j > 0 && to[j - 1] != '/') {
                if (j < tolen - 1) {
                    to[j++] = '/';
                } else {
                    return -ENAMETOOLONG;
                }
            }
        } else {
            return -EINVAL;
        }
    }

    if (j >= tolen) {
        return -ENAMETOOLONG;
    }

    to[j] = '\0';

    return 0;
}

